Supports mg, g, mcg, kg, mL, L and the compounds mg/mL and mg/kg.
Pure stdlib.
"""
from __future__ import annotations

import math

# canonical mass unit: mg -- canonical volume unit: mL
_DIM = {"mcg": "mass", "mg": "mass", "g": "mass", "kg": "mass",
        "mL": "volume", "L": "volume"}
_FACTOR = {"mcg": 1e-3, "mg": 1.0, "g": 1e3, "kg": 1e6,
           "mL": 1.0, "L": 1e3}
_KNOWN = set(_FACTOR) | {"mg/mL", "mg/kg"}


class UnitError(Exception):
    """Raised for unit-incompatible operations."""


def _parse(text: str) -> dict:
    """Parse 'mg', 'mg/mL', 'mg*kg/mL' ... into {name: exponent}."""
    if text in _FACTOR:
        return {text: 1}
    if text in ("", "1"):
        return {}
    sides = text.split("/")
    if len(sides) > 2 or not all(sides):
        raise UnitError(f"cannot parse unit {text!r}")
    parts, sign = {}, 1
    for side in sides:
        for name in side.split("*"):
            if name not in _FACTOR:
                raise UnitError(f"unknown unit {name!r}")
            parts[name] = parts.get(name, 0) + sign
        sign = -1
    return {k: v for k, v in parts.items() if v}


def _fmt(parts: dict) -> str:
    def term(name, exp):
        return name if abs(exp) == 1 else f"{name}^{exp}"
    num = [term(n, e) for n, e in parts.items() if e > 0]
    den = [term(n, -e) for n, e in parts.items() if e < 0]
    out = "*".join(num)
    if den:
        out += "/" + "*".join(den)
    return out or "1"


def _factor_of(parts: dict) -> float:
    f = 1.0
    for n, e in parts.items():
        f *= _FACTOR[n] ** e
    return f


def _signature(parts: dict) -> dict:
    sig = {}
    for n, e in parts.items():
        sig[_DIM[n]] = sig.get(_DIM[n], 0) + e
    return {d: e for d, e in sig.items() if e}


class Unit:
    """A (possibly compound) unit, e.g. mg, kg, mg/mL."""

    __slots__ = ("parts",)

    def __init__(self, spec="1"):
        if isinstance(spec, Unit):
            self.parts = dict(spec.parts)
        elif isinstance(spec, dict):
            self.parts = {k: int(v) for k, v in spec.items() if v}
        else:
            self.parts = _parse(str(spec))

    @property
    def factor(self) -> float:
        return _factor_of(self.parts)

    @property
    def signature(self) -> dict:
        return _signature(self.parts)

    def __str__(self):
        return _fmt(self.parts)

    def __repr__(self):
        return f"Unit({str(self)!r})"

    def __eq__(self, other):
        return isinstance(other, Unit) and self.parts == other.parts

    def __hash__(self):
        return hash(tuple(sorted(self.parts.items())))

    def __mul__(self, other):
        if isinstance(other, Unit):
            p = dict(self.parts)
            for n, e in other.parts.items():
                p[n] = p.get(n, 0) + e
            return Unit(p)
        return NotImplemented

    def __truediv__(self, other):
        if isinstance(other, Unit):
            return self * Unit({n: -e for n, e in other.parts.items()})
        return NotImplemented

    def __rmul__(self, scalar):
        if isinstance(scalar, (int, float)):
            return Quantity(scalar, self)
        return NotImplemented


def _display(parts: dict, canon: float):
    """Pick a display unit for combined parts; return (unit, value).

    `canon` is the physical amount expressed in canonical composite units
    (mg for mass, mL for volume powers).
    """
    unit = Unit(parts)
    if str(unit) not in _KNOWN:
        cp = {}
        for n, e in parts.items():
            cu = "mg" if _DIM[n] == "mass" else "mL"
            cp[cu] = cp.get(cu, 0) + e
        unit = Unit(cp)
    return unit, canon / unit.factor


class Quantity:
    """A magnitude together with a unit."""

    __slots__ = ("value", "unit")

    def __init__(self, value, unit):
        self.value = value
        self.unit = unit if isinstance(unit, Unit) else Unit(unit)

    @property
    def _canon(self):
        return self.value * self.unit.factor

    def _compatible(self, other):
        return (isinstance(other, Quantity)
                and self.unit.signature == other.unit.signature)

    def __add__(self, other):
        if not self._compatible(other):
            raise UnitError(
                f"cannot add {self} to {other}: incompatible units")
        res = (self.unit if self.unit.factor <= other.unit.factor
               else other.unit)
        return Quantity((self._canon + other._canon) / res.factor, res)

    def __sub__(self, other):
        if not self._compatible(other):
            raise UnitError(
                f"cannot subtract {other} from {self}: incompatible units")
        return self + Quantity(-other.value, other.unit)

    def __neg__(self):
        return Quantity(-self.value, self.unit)

    def __mul__(self, other):
        if isinstance(other, Quantity):
            p = dict(self.unit.parts)
            for n, e in other.unit.parts.items():
                p[n] = p.get(n, 0) + e
            unit, value = _display(p, self._canon * other._canon)
            return Quantity(value, unit)
        if isinstance(other, (int, float)):
            return Quantity(self.value * other, self.unit)
        return NotImplemented

    __rmul__ = __mul__

    def __truediv__(self, other):
        if isinstance(other, Quantity):
            p = dict(self.unit.parts)
            for n, e in other.unit.parts.items():
                p[n] = p.get(n, 0) - e
            unit, value = _display(p, self._canon / other._canon)
            return Quantity(value, unit)
        if isinstance(other, (int, float)):
            if other == 0:
                raise UnitError("division by zero")
            return Quantity(self.value / other, self.unit)
        return NotImplemented

    def __eq__(self, other):
        return (self._compatible(other)
                and math.isclose(self._canon, other._canon,
                                 rel_tol=1e-12, abs_tol=1e-12))

    def __hash__(self):
        return hash((round(self._canon, 12), str(self.unit.signature)))

    def __str__(self):
        return f"{self.value:g} {self.unit}"

    def __repr__(self):
        return f"Quantity({self.value!r}, {str(self.unit)!r})"


