    """Weight-based dose -> infusion volume, via dimensional analysis."""
    dose = Quantity(dose_mg_per_kg, "mg/kg") * Quantity(weight_kg, "kg")
    return dose / Quantity(conc_mg_per_mL, "mg/mL")
